/**
 * Limpia signos de apertura (¿ ¡) y colapsa saltos de línea dobles a simples \n
 */
function cleanString(str) {
  if (typeof str !== "string") return str;

  return str
    .replace(/[¿¡]/g, "")
    .replace(/\n{2,}/g, "\n");
}

/**
 * Limpia recursivamente strings dentro de objetos/arrays (por si el modelo devuelve anidados)
 */
function deepClean(value) {
  if (typeof value === "string") return cleanString(value);

  if (Array.isArray(value)) {
    return value.map(deepClean);
  }

  if (value && typeof value === "object") {
    const out = {};
    for (const [k, v] of Object.entries(value)) out[k] = deepClean(v);
    return out;
  }

  return value;
}

const items = $input.all();

return items.map((item) => {
  // Por las dudas, si alguna vez te llega como string JSON
  const json = typeof item.json === "string" ? JSON.parse(item.json) : item.json;

  // Estructura del nodo "Message a model": json.output[] -> content[] -> (type=output_text) -> text
  if (Array.isArray(json.output)) {
    json.output = json.output.map((msg) => {
      if (!Array.isArray(msg.content)) return msg;

      msg.content = msg.content.map((c) => {
        if (c?.type === "output_text" && c.hasOwnProperty("text")) {
          c.text = deepClean(c.text);
        }
        return c;
      });

      return msg;
    });
  }

  return { json };
});

